def render_contract(s):
 s.render.engine='CYCLES';s.cycles.samples=128;s.cycles.use_adaptive_sampling=False;s.cycles.use_denoising=False
 s.render.threads_mode='FIXED';s.render.threads=4;s.use_nodes=False;s.render.use_compositing=False
 for layer in s.view_layers:layer.cycles.use_denoising=False
 s.render.resolution_x=768;s.render.resolution_y=768;s.render.resolution_percentage=100
 return config_snapshot(s)
def config_snapshot(s):
 return {'engine':s.render.engine,'samples':s.cycles.samples,'adaptive_sampling':s.cycles.use_adaptive_sampling,'cycles_denoising':s.cycles.use_denoising,'view_layers_denoising':{v.name:v.cycles.use_denoising for v in s.view_layers},'threads_mode':s.render.threads_mode,'threads':s.render.threads,'compositor_nodes':s.use_nodes,'render_use_compositing':s.render.use_compositing,'resolution':[s.render.resolution_x,s.render.resolution_y,s.render.resolution_percentage]}


def pbr(m):
 n=m.node_tree.nodes['Principled BSDF']
 return tuple(round(float(v),6) for v in n.inputs['Base Color'].default_value)+(round(float(n.inputs['Roughness'].default_value),6),round(float(n.inputs['Metallic'].default_value),6))
def records(obs,transform=None,local=False):
 rows=[]
